"""Submit a regression suite's results to ASTRA's reporting service."""

import json
import os
import sys
from datetime import datetime
from pathlib import Path

import requests

# Tests that were not run (e.g., after a setup failure) are reported as skipped.
ASTRA_STATUSES = {
    "passed": "passed",
    "failed": "failed",
    "skipped": "skipped",
    "not run": "skipped",
}


def get_test_results(sub_dir: str) -> list[dict]:
    """Read per-test results generated by notebook_report.py, if available."""
    results_file = Path("/workdir/output") / sub_dir / "test_results.json"
    if not results_file.exists():
        return []

    try:
        results = json.loads(results_file.read_text())["tests"]
    except (KeyError, ValueError) as exception:
        print(f"Could not read {results_file}: {exception}", file=sys.stderr)
        return []

    return [
        {
            "title": result["title"],
            "status": ASTRA_STATUSES[result["status"]],
            "duration": result["duration"],
        }
        for result in results
    ]


def main() -> None:
    reporting_url = os.getenv("ETQ_REPORTING_URL")
    if not reporting_url:
        print("ETQ_REPORTING_URL is not set; skipping results submission.")
        return

    sub_dir = os.environ["env_sub_dir"]
    notebook = os.environ["env_notebook"]
    status, start_raw, end_raw = sys.argv[1], sys.argv[2], sys.argv[3]
    start = datetime.strptime(start_raw, "%Y-%m-%dT%H:%M:%S.%f%z")
    end = datetime.strptime(end_raw, "%Y-%m-%dT%H:%M:%S.%f%z")
    duration = (end - start).total_seconds()

    tests = get_test_results(sub_dir)
    if not tests:
        tests = [{"title": notebook, "status": status, "duration": duration}]

    response = requests.post(
        url=f"{reporting_url}/v1/results",
        json={
            "title": sub_dir,
            "start": start.isoformat(),
            "end": end.isoformat(),
            "duration": duration,
            "tests": tests,
        },
    )
    response.raise_for_status()
    print(f"Results submitted with ID {response.json()['id']}.")


if __name__ == "__main__":
    main()
